# ---------------------------------------------------------------------
# 3. Generic semantic retrieval
# ---------------------------------------------------------------------

def retrieve_from_preserved_document(
    result,
    question,
    top_k=6,
):
    """
    Retrieve the most similar dry-run chunks using cosine similarity.
    Embeddings are normalized, so dot product equals cosine similarity.
    """
    query_embedding = (
        embedding_model.encode(
            [question],
            convert_to_numpy=True,
            normalize_embeddings=True,
            show_progress_bar=False,
        )[0]
    )

    document_embeddings = (
        result["embeddings"]
    )

    similarity_scores = (
        document_embeddings
        @ query_embedding
    )

    top_indexes = np.argsort(
        similarity_scores
    )[::-1][:top_k]

    retrieved = []

    for rank, chunk_index in enumerate(
        top_indexes,
        start=1,
    ):
        chunk = result["chunks"][
            int(chunk_index)
        ]

        retrieved.append(
            {
                "rank": rank,
                "chunk_index": int(
                    chunk_index
                ),
                "score": float(
                    similarity_scores[
                        chunk_index
                    ]
                ),
                "text": chunk["text"],
                "section": chunk.get(
                    "section",
                    "Unknown section",
                ),
                "chunk_type": chunk.get(
                    "chunk_type",
                    "unknown",
                ),
            }
        )

    return retrieved


def expected_groups_found(
    retrieved_chunks,
    expected_groups,
):
    """
    Every expected group must have at least one matching alternative
    somewhere in the retrieved context.
    """
    combined_context = " ".join(
        item["text"]
        for item in retrieved_chunks
    ).lower()

    group_results = []

    for alternatives in expected_groups:
        matched_alternative = next(
            (
                alternative
                for alternative
                in alternatives
                if alternative.lower()
                in combined_context
            ),
            None,
        )

        group_results.append(
            {
                "alternatives": alternatives,
                "matched": (
                    matched_alternative
                ),
            }
        )

    passed = all(
        group["matched"]
        is not None
        for group in group_results
    )

    return passed, group_results


