def load_seed_chunks_from_qdrant(
    tenant_id,
):
    """
    Load every text payload for one validated seed tenant.
    """
    points = []
    next_offset = None

    tenant_filter = Filter(
        must=[
            FieldCondition(
                key=TENANT_ID_FIELD,
                match=MatchValue(
                    value=tenant_id
                ),
            )
        ]
    )

    while True:
        batch, next_offset = qdrant.scroll(
            collection_name=COLLECTION_NAME,
            scroll_filter=tenant_filter,
            limit=256,
            offset=next_offset,
            with_payload=True,
            with_vectors=False,
        )

        points.extend(batch)

        if next_offset is None:
            break

    chunks = []

    for point in points:
        payload = point.payload or {}

        chunk_text = str(
            payload.get(
                TEXT_FIELD,
                "",
            )
        ).strip()

        if not chunk_text:
            continue

        chunks.append(
            {
                "text": chunk_text,
                "chunk_type": payload.get(
                    CHUNK_TYPE_FIELD,
                    "unknown",
                ),
               "section": payload.get(
    "section",
    "Unknown section",
),
"chunk_index": payload.get(
    CHUNK_INDEX_FIELD,
    len(chunks),
),
            }
        )

    if not chunks:
        raise RuntimeError(
            f"No seed chunks found for tenant: "
            f"{tenant_id}"
        )

    return chunks


