def normalize_comparison_text(text):
    normalized = " ".join(
        str(text or "").lower().split()
    )

    compact = "".join(
        character
        for character in normalized
        if character.isalnum()
    )

    return normalized, compact


def chunk_contains_expected_groups(
    text,
    expected_groups,
):
    normalized_text, compact_text = (
        normalize_comparison_text(
            text
        )
    )

    for alternatives in expected_groups:
        group_found = False

        for alternative in alternatives:
            (
                normalized_alternative,
                compact_alternative,
            ) = normalize_comparison_text(
                alternative
            )

            if (
                normalized_alternative
                in normalized_text
                or (
                    compact_alternative
                    and compact_alternative
                    in compact_text
                )
            ):
                group_found = True
                break

        if not group_found:
            return False

    return True


def evaluate_one_chunk_set(
    result,
    question,
    expected_groups,
    retrieval_depth=20,
):
    retrieved = retrieve_hybrid(
        result=result,
        question=question,
        top_k=retrieval_depth,
    )

    best_complete_rank = None

    for item in retrieved:
        if chunk_contains_expected_groups(
            item["text"],
            expected_groups,
        ):
            best_complete_rank = item[
                "rank"
            ]
            break

    context_passed, group_results = (
        hybrid_expected_groups_found(
            retrieved[:6],
            expected_groups,
        )
    )

    return {
        "retrieved": retrieved,
        "best_complete_rank": (
            best_complete_rank
        ),
        "top_6_context_passed": (
            context_passed
        ),
        "group_results": (
            group_results
        ),
    }


