def prepare_v2_retrieval_result(
    label,
    preserved_document,
):
    chunks = preserved_document[
        "chunks"
    ]

    print(
        f"⏳ Preparing {label}: "
        f"{len(chunks)} chunks"
    )

    embeddings = embedding_model.encode(
        [
            chunk["text"]
            for chunk in chunks
        ],
        batch_size=64,
        convert_to_numpy=True,
        normalize_embeddings=True,
        show_progress_bar=True,
    )

    result = {
        "filename": label,
        "chunks": chunks,
        "embeddings": embeddings,
    }

    result["bm25_index"] = (
        build_bm25_index(
            chunks
        )
    )

    return result


