# ---------------------------------------------------------------------
# 5. Evidence matching
# ---------------------------------------------------------------------

def normalize_v2_evidence(text):
    normalized = " ".join(
        str(text or "")
        .lower()
        .split()
    )

    compact = re.sub(
        r"[^a-z0-9]+",
        "",
        normalized,
    )

    return normalized, compact


def v2_text_contains_groups(
    text,
    expected_groups,
):
    normalized_text, compact_text = (
        normalize_v2_evidence(
            text
        )
    )

    for alternatives in expected_groups:
        group_found = False

        for alternative in alternatives:
            (
                normalized_alternative,
                compact_alternative,
            ) = normalize_v2_evidence(
                alternative
            )

            if (
                normalized_alternative
                in normalized_text
                or (
                    compact_alternative
                    and compact_alternative
                    in compact_text
                )
            ):
                group_found = True
                break

        if not group_found:
            return False

    return True


def evaluate_v2_chunk_set(
    result,
    question,
    expected_groups,
    retrieval_depth=20,
):
    retrieved = retrieve_hybrid(
        result=result,
        question=question,
        top_k=retrieval_depth,
    )

    complete_evidence_rank = None

    for item in retrieved:
        if v2_text_contains_groups(
            item["text"],
            expected_groups,
        ):
            complete_evidence_rank = (
                item["rank"]
            )
            break

    combined_top_6_context = " ".join(
        item["text"]
        for item in retrieved[:6]
    )

    top_6_context_passed = (
        v2_text_contains_groups(
            combined_top_6_context,
            expected_groups,
        )
    )

    return {
        "retrieved": retrieved,
        "complete_evidence_rank": (
            complete_evidence_rank
        ),
        "top_6_context_passed": (
            top_6_context_passed
        ),
    }


