# VAULTIFY COMPACT - Cell 21A:
# Build the tenant document catalog for Retrieval Orchestrator V1
#
# READ-ONLY:
# - Reads Qdrant payloads for one tenant
# - Groups chunks by document
# - Detects document entities, aliases, sections, years, and chunk types
# - Does not generate embeddings
# - Does not modify Qdrant

from collections import Counter, defaultdict
from pathlib import Path
import re

from qdrant_client.models import (
    FieldCondition,
    Filter,
    MatchValue,
)


# ---------------------------------------------------------------------
# 1. Resolve runtime dependencies
# ---------------------------------------------------------------------

if "qdrant" not in globals():
    raise RuntimeError(
        "The Qdrant client was not found. "
        "Run the Qdrant connection cells first."
    )


ORCHESTRATOR_COLLECTION_NAME = globals().get(
    "COLLECTION_NAME",
    "vaultify_v3_documents",
)

ORCHESTRATOR_TENANT_FIELD = globals().get(
    "TENANT_ID_FIELD",
    "tenant_id",
)


# Prefer a previously selected orchestrator tenant.
if globals().get("ORCHESTRATOR_TENANT_ID"):
    ORCHESTRATOR_TENANT_ID = str(
        ORCHESTRATOR_TENANT_ID
    )

# Otherwise use the validated Apple demo tenant.
elif (
    "DEMO_TENANTS" in globals()
    and isinstance(DEMO_TENANTS, dict)
    and "company_a" in DEMO_TENANTS
):
    company_a_config = DEMO_TENANTS[
        "company_a"
    ]

    if isinstance(company_a_config, dict):
        ORCHESTRATOR_TENANT_ID = str(
            company_a_config.get(
                "tenant_id",
                "demo_apple_tenant",
            )
        )
    else:
        ORCHESTRATOR_TENANT_ID = (
            "demo_apple_tenant"
        )

else:
    ORCHESTRATOR_TENANT_ID = (
        "demo_apple_tenant"
    )


print(
    f"🏢 Orchestrator tenant: "
    f"{ORCHESTRATOR_TENANT_ID}"
)

print(
    f"📦 Qdrant collection: "
    f"{ORCHESTRATOR_COLLECTION_NAME}"
)


# ---------------------------------------------------------------------
# 2. Payload compatibility helpers
# ---------------------------------------------------------------------

def first_payload_value(
    payload,
    candidate_keys,
    default=None,
):
    """
    Return the first non-empty payload value among several
    compatible field names.
    """
    for key in candidate_keys:
        value = payload.get(key)

        if value is not None and value != "":
            return value

    return default


def payload_text(payload):
    return str(
        first_payload_value(
            payload,
            [
                "text",
                "content",
                "page_content",
                "chunk_text",
            ],
            "",
        )
    ).strip()


def payload_filename(payload):
    return str(
        first_payload_value(
            payload,
            [
                "filename",
                "file_name",
                "document_name",
                "source",
            ],
            "unknown_document",
        )
    ).strip()


def payload_document_hash(payload):
    value = first_payload_value(
        payload,
        [
            "document_hash",
            "file_hash",
            "sha256",
            "document_id",
        ],
        None,
    )

    if value is None:
        return None

    return str(value).strip()


def payload_section(payload):
    return str(
        first_payload_value(
            payload,
            [
                "section",
                "section_name",
                "heading",
                "title",
            ],
            "Unknown section",
        )
    ).strip()


def payload_chunk_type(payload):
    return str(
        first_payload_value(
            payload,
            [
                "chunk_type",
                "type",
                "content_type",
            ],
            "unknown",
        )
    ).strip().lower()


def payload_chunk_index(
    payload,
    fallback_index,
):
    value = first_payload_value(
        payload,
        [
            "chunk_index",
            "index",
            "chunk_id",
        ],
        fallback_index,
    )

    try:
        return int(value)
    except (TypeError, ValueError):
        return fallback_index


# ---------------------------------------------------------------------
# 3. Read every point belonging to the selected tenant
# ---------------------------------------------------------------------

def load_tenant_points(
    tenant_id,
    batch_size=256,
):
    tenant_filter = Filter(
        must=[
            FieldCondition(
                key=ORCHESTRATOR_TENANT_FIELD,
                match=MatchValue(
                    value=tenant_id
                ),
            )
        ]
    )

    points = []
    next_offset = None

    while True:
        batch, next_offset = qdrant.scroll(
            collection_name=(
                ORCHESTRATOR_COLLECTION_NAME
            ),
            scroll_filter=tenant_filter,
            limit=batch_size,
            offset=next_offset,
            with_payload=True,
            with_vectors=False,
        )

        points.extend(batch)

        if next_offset is None:
            break

    return points


print(
    "\n⏳ Reading tenant payloads "
    "from Qdrant..."
)

tenant_points = load_tenant_points(
    ORCHESTRATOR_TENANT_ID
)

if not tenant_points:
    raise RuntimeError(
        "No Qdrant points were found for tenant "
        f"'{ORCHESTRATOR_TENANT_ID}'."
    )

print(
    f"✅ Tenant points loaded: "
    f"{len(tenant_points)}"
)


# ---------------------------------------------------------------------
# 4. Convert Qdrant points into normalized chunk records
# ---------------------------------------------------------------------

ORCHESTRATOR_TENANT_CHUNKS = []

for fallback_index, point in enumerate(
    tenant_points
):
    payload = point.payload or {}

    text = payload_text(payload)

    if not text:
        continue

    filename = payload_filename(
        payload
    )

    document_hash = payload_document_hash(
        payload
    )

    ORCHESTRATOR_TENANT_CHUNKS.append(
        {
            "point_id": str(point.id),
            "tenant_id": (
                ORCHESTRATOR_TENANT_ID
            ),
            "filename": filename,
            "document_hash": (
                document_hash
            ),
            "chunk_index": (
                payload_chunk_index(
                    payload,
                    fallback_index,
                )
            ),
            "chunk_type": (
                payload_chunk_type(
                    payload
                )
            ),
            "section": (
                payload_section(
                    payload
                )
            ),
            "text": text,
            "payload": payload,
        }
    )


if not ORCHESTRATOR_TENANT_CHUNKS:
    raise RuntimeError(
        "Tenant points existed, but no usable "
        "chunk text was found."
    )


# ---------------------------------------------------------------------
# 5. Deterministic V1 entity and alias inference
# ---------------------------------------------------------------------

KNOWN_ENTITY_RULES = {
    "Apple": {
        "filename_terms": {
            "apple",
            "aapl",
        },
        "content_terms": {
            "apple inc",
        },
        "aliases": {
            "apple",
            "apple inc",
            "aapl",
        },
    },

    "Tesla": {
        "filename_terms": {
            "tesla",
            "tsla",
        },
        "content_terms": {
            "tesla inc",
        },
        "aliases": {
            "tesla",
            "tesla inc",
            "tsla",
        },
    },

    "NIST": {
        "filename_terms": {
            "nist",
        },
        "content_terms": {
            "national institute "
            "of standards and technology",
        },
        "aliases": {
            "nist",
            "national institute "
            "of standards and technology",
        },
    },
}


def normalize_catalog_text(text):
    normalized = str(
        text or ""
    ).lower()

    normalized = re.sub(
        r"[_\-]+",
        " ",
        normalized,
    )

    normalized = re.sub(
        r"\s+",
        " ",
        normalized,
    )

    return normalized.strip()


def infer_document_entities(
    filename,
    chunks,
):
    normalized_filename = (
        normalize_catalog_text(
            filename
        )
    )

    sample_content = " ".join(
        chunk["text"]
        for chunk in chunks[:20]
    )

    normalized_content = (
        normalize_catalog_text(
            sample_content
        )
    )

    detected_entities = []

    for entity, rule in (
        KNOWN_ENTITY_RULES.items()
    ):
        filename_match = any(
            term in normalized_filename
            for term in rule[
                "filename_terms"
            ]
        )

        content_match = any(
            term in normalized_content
            for term in rule[
                "content_terms"
            ]
        )

        if filename_match or content_match:
            detected_entities.append(
                entity
            )

    # Generic fallback for unknown future documents.
    if not detected_entities:
        fallback_name = Path(
            filename
        ).stem

        fallback_name = re.sub(
            r"[_\-]+",
            " ",
            fallback_name,
        )

        fallback_name = re.sub(
            r"\s+",
            " ",
            fallback_name,
        ).strip()

        detected_entities.append(
            fallback_name
            or "Unknown entity"
        )

    return detected_entities


def aliases_for_entities(
    entities,
):
    aliases = set()

    for entity in entities:
        rule = KNOWN_ENTITY_RULES.get(
            entity
        )

        if rule:
            aliases.update(
                rule["aliases"]
            )
        else:
            aliases.add(
                normalize_catalog_text(
                    entity
                )
            )

    return sorted(aliases)


# ---------------------------------------------------------------------
# 6. Group chunks by document
# ---------------------------------------------------------------------

document_groups = defaultdict(list)

for chunk in ORCHESTRATOR_TENANT_CHUNKS:
    document_hash = chunk[
        "document_hash"
    ]

    filename = chunk[
        "filename"
    ]

    # Prefer the SHA-256 document hash.
    # Fall back to filename for older seed payloads.
    document_key = (
        document_hash
        if document_hash
        else f"filename::{filename.lower()}"
    )

    document_groups[
        document_key
    ].append(chunk)


ORCHESTRATOR_DOCUMENT_CATALOG = {}
ORCHESTRATOR_ENTITY_REGISTRY = (
    defaultdict(
        lambda: {
            "aliases": set(),
            "document_keys": set(),
            "filenames": set(),
        }
    )
)


YEAR_PATTERN = re.compile(
    r"\b(?:19|20)\d{2}\b"
)


for document_key, chunks in (
    document_groups.items()
):
    chunks.sort(
        key=lambda chunk: (
            chunk["chunk_index"],
            chunk["point_id"],
        )
    )

    filename_counts = Counter(
        chunk["filename"]
        for chunk in chunks
    )

    filename = filename_counts.most_common(
        1
    )[0][0]

    document_hash = next(
        (
            chunk["document_hash"]
            for chunk in chunks
            if chunk["document_hash"]
        ),
        None,
    )

    chunk_type_counts = Counter(
        chunk["chunk_type"]
        for chunk in chunks
    )

    section_counts = Counter(
        chunk["section"]
        for chunk in chunks
        if chunk["section"]
    )

    year_counts = Counter()

    for chunk in chunks:
        year_counts.update(
            YEAR_PATTERN.findall(
                chunk["text"]
            )
        )

    entities = infer_document_entities(
        filename=filename,
        chunks=chunks,
    )

    aliases = aliases_for_entities(
        entities
    )

    catalog_entry = {
        "document_key": document_key,
        "filename": filename,
        "document_hash": (
            document_hash
        ),
        "tenant_id": (
            ORCHESTRATOR_TENANT_ID
        ),
        "chunk_count": len(chunks),
        "chunk_types": dict(
            chunk_type_counts
        ),
        "entities": entities,
        "aliases": aliases,
        "top_years": [
            {
                "year": year,
                "mentions": count,
            }
            for year, count
            in year_counts.most_common(10)
        ],
        "top_sections": [
            {
                "section": section,
                "chunks": count,
            }
            for section, count
            in section_counts.most_common(12)
        ],
        "chunks": chunks,
    }

    ORCHESTRATOR_DOCUMENT_CATALOG[
        document_key
    ] = catalog_entry

    for entity in entities:
        registry_entry = (
            ORCHESTRATOR_ENTITY_REGISTRY[
                entity
            ]
        )

        registry_entry[
            "aliases"
        ].update(aliases)

        registry_entry[
            "document_keys"
        ].add(document_key)

        registry_entry[
            "filenames"
        ].add(filename)


# Convert defaultdict and sets to stable dictionaries/lists.
ORCHESTRATOR_ENTITY_REGISTRY = {
    entity: {
        "aliases": sorted(
            metadata["aliases"]
        ),
        "document_keys": sorted(
            metadata["document_keys"]
        ),
        "filenames": sorted(
            metadata["filenames"]
        ),
    }
    for entity, metadata
    in ORCHESTRATOR_ENTITY_REGISTRY.items()
}


# ---------------------------------------------------------------------
# 7. Validate the mixed-corpus fixture
# ---------------------------------------------------------------------

catalog_entities = {
    entity
    for document
    in ORCHESTRATOR_DOCUMENT_CATALOG.values()
    for entity
    in document["entities"]
}

ORCHESTRATOR_MIXED_CORPUS_READY = (
    "Apple" in catalog_entities
    and "Tesla" in catalog_entities
)


# ---------------------------------------------------------------------
# 8. Print catalog summary
# ---------------------------------------------------------------------

print("\n" + "=" * 92)
print("📚 RETRIEVAL ORCHESTRATOR DOCUMENT CATALOG")

print(
    f"Tenant: "
    f"{ORCHESTRATOR_TENANT_ID}"
)

print(
    f"Documents: "
    f"{len(ORCHESTRATOR_DOCUMENT_CATALOG)}"
)

print(
    f"Usable chunks: "
    f"{len(ORCHESTRATOR_TENANT_CHUNKS)}"
)


for document_number, document in enumerate(
    ORCHESTRATOR_DOCUMENT_CATALOG.values(),
    start=1,
):
    print("\n" + "-" * 92)

    print(
        f"📄 Document {document_number}: "
        f"{document['filename']}"
    )

    print(
        f"   Document hash: "
        f"{document['document_hash'] or 'not available'}"
    )

    print(
        f"   Chunks: "
        f"{document['chunk_count']}"
    )

    print(
        f"   Types: "
        f"{document['chunk_types']}"
    )

    print(
        f"   Entities: "
        f"{document['entities']}"
    )

    print(
        f"   Aliases: "
        f"{document['aliases']}"
    )

    print(
        "   Most frequent years: "
        + ", ".join(
            f"{item['year']} "
            f"({item['mentions']})"
            for item
            in document["top_years"][:6]
        )
    )

    print(
        "   Top sections:"
    )

    for section_entry in (
        document["top_sections"][:5]
    ):
        print(
            f"      "
            f"{section_entry['chunks']:>3} chunks"
            f" — "
            f"{section_entry['section']}"
        )


print("\n" + "=" * 92)
print("🏷️ ENTITY REGISTRY")

for entity, metadata in (
    ORCHESTRATOR_ENTITY_REGISTRY.items()
):
    print(
        f"\n{entity}"
    )

    print(
        f"   Aliases: "
        f"{metadata['aliases']}"
    )

    print(
        f"   Documents: "
        f"{metadata['filenames']}"
    )


print("\n" + "=" * 92)

if ORCHESTRATOR_MIXED_CORPUS_READY:
    print(
        "✅ Mixed Apple + Tesla corpus detected."
    )

    print(
        "✅ Tenant document catalog is ready "
        "for Query Analyzer V1."
    )

else:
    print(
        "⚠️ Apple + Tesla mixed corpus was not "
        "fully detected."
    )

    print(
        "Review the entity registry before "
        "continuing to Cell 21B."
    )


print(
    "\n⏭️ No embeddings were generated."
)

print(
    "⏭️ No Qdrant points were created, "
    "updated, or deleted."
)

# VAULTIFY COMPACT - Cell 21B:
# Deterministic Query Analyzer V1 for Retrieval Orchestrator
#
# READ-ONLY:
# - Detects entities, metrics, periods, comparisons, and ambiguity
# - Produces entity-specific subqueries
# - Does not call Groq
# - Does not generate embeddings
# - Does not modify Qdrant

from copy import deepcopy
import re


# ---------------------------------------------------------------------
# 1. Validate Cell 21A outputs
# ---------------------------------------------------------------------

required_names = [
    "ORCHESTRATOR_DOCUMENT_CATALOG",
    "ORCHESTRATOR_ENTITY_REGISTRY",
    "ORCHESTRATOR_MIXED_CORPUS_READY",
]

missing_names = [
    name
    for name in required_names
    if name not in globals()
]

if missing_names:
    raise RuntimeError(
        "Missing Cell 21A components: "
        + ", ".join(missing_names)
    )


if not ORCHESTRATOR_ENTITY_REGISTRY:
    raise RuntimeError(
        "The entity registry is empty."
    )


# ---------------------------------------------------------------------
# 2. Analyzer configuration
# ---------------------------------------------------------------------

COMPARISON_PATTERNS = [
    r"\bcompare\b",
    r"\bcomparison\b",
    r"\bversus\b",
    r"\bvs\.?\b",
    r"\bcompared\s+with\b",
    r"\bcompared\s+to\b",
    r"\bdifference\s+between\b",
    r"\bhow\s+does\b.*\bcompare\b",
]


METRIC_RULES = [
    {
        "canonical": "total_net_sales",
        "label": "total net sales",
        "patterns": [
            r"\btotal\s+net\s+sales\b",
            r"\bnet\s+sales\s+total\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "services_net_sales",
        "label": "services net sales",
        "patterns": [
            r"\bservices?\s+net\s+sales\b",
            r"\bnet\s+sales\s+from\s+services\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "iphone_net_sales",
        "label": "iPhone net sales",
        "patterns": [
            r"\biphone\s+net\s+sales\b",
            r"\bnet\s+sales\s+from\s+iphone\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "automotive_revenue",
        "label": "automotive revenue",
        "patterns": [
            r"\bautomotive\s+revenues?\b",
            r"\btotal\s+automotive\s+revenues?\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "energy_storage_revenue",
        "label": (
            "energy generation and storage revenue"
        ),
        "patterns": [
            (
                r"\benergy\s+generation\s+"
                r"(?:and|&)\s+storage\s+revenues?\b"
            ),
            (
                r"\benergy\s+storage\s+revenues?\b"
            ),
        ],
        "quantitative": True,
    },
    {
        "canonical": "gaap_operating_income",
        "label": "GAAP operating income",
        "patterns": [
            r"\bgaap\s+operating\s+income\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "operating_income",
        "label": "operating income",
        "patterns": [
            r"\boperating\s+income\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "total_revenue",
        "label": "total revenue",
        "patterns": [
            r"\btotal\s+revenues?\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "net_sales",
        "label": "net sales",
        "patterns": [
            r"\bnet\s+sales\b",
        ],
        "quantitative": True,
    },
    {
        "canonical": "revenue",
        "label": "revenue",
        "patterns": [
            r"\brevenues?\b",
        ],
        "quantitative": True,
    },
]


DOCUMENT_SCOPE_PATTERNS = [
    r"\baccording\s+to\s+the\s+documents?\b",
    r"\bin\s+the\s+documents?\b",
    r"\bin\s+the\s+reports?\b",
    r"\bin\s+the\s+files?\b",
    r"\bsummarize\b",
    r"\bdocuments?\s+say\b",
    r"\breports?\s+say\b",
    r"\bacross\s+the\s+documents?\b",
]


# ---------------------------------------------------------------------
# 3. Normalization helpers
# ---------------------------------------------------------------------

def normalize_query_text(text):
    normalized = str(
        text or ""
    )

    normalized = (
        normalized
        .replace("’", "'")
        .replace("‘", "'")
        .replace("“", '"')
        .replace("”", '"')
    )

    normalized = normalized.lower()

    normalized = re.sub(
        r"\bfy\s*[- ]?(\d{4})\b",
        r"fiscal year \1",
        normalized,
    )

    normalized = re.sub(
        r"\bfiscal\s+(\d{4})\b",
        r"fiscal year \1",
        normalized,
    )

    normalized = re.sub(
        r"\bq\s*([1-4])\s*[- ]?(\d{4})\b",
        r"q\1 \2",
        normalized,
    )

    normalized = re.sub(
        r"\s+",
        " ",
        normalized,
    )

    return normalized.strip()


# ---------------------------------------------------------------------
# 4. Entity alias index
# ---------------------------------------------------------------------

def build_entity_alias_index(
    entity_registry,
):
    alias_records = []

    for entity, metadata in (
        entity_registry.items()
    ):
        aliases = set(
            metadata.get(
                "aliases",
                [],
            )
        )

        aliases.add(
            entity.lower()
        )

        for alias in aliases:
            normalized_alias = (
                normalize_query_text(
                    alias
                )
            )

            if not normalized_alias:
                continue

            alias_records.append(
                {
                    "entity": entity,
                    "alias": normalized_alias,
                }
            )

    # Prefer longer aliases such as "apple inc"
    # before shorter aliases such as "apple".
    alias_records.sort(
        key=lambda item: len(
            item["alias"]
        ),
        reverse=True,
    )

    return alias_records


ORCHESTRATOR_ENTITY_ALIAS_INDEX = (
    build_entity_alias_index(
        ORCHESTRATOR_ENTITY_REGISTRY
    )
)


def detect_entity_mentions(
    normalized_question,
):
    mentions = []
    occupied_ranges = []

    for alias_record in (
        ORCHESTRATOR_ENTITY_ALIAS_INDEX
    ):
        entity = alias_record[
            "entity"
        ]

        alias = alias_record[
            "alias"
        ]

        alias_pattern = (
            r"(?<![a-z0-9])"
            + re.escape(alias)
            + r"(?:'s)?"
            + r"(?![a-z0-9])"
        )

        for match in re.finditer(
            alias_pattern,
            normalized_question,
        ):
            start, end = match.span()

            overlaps_existing = any(
                start < occupied_end
                and end > occupied_start
                for (
                    occupied_start,
                    occupied_end,
                )
                in occupied_ranges
            )

            if overlaps_existing:
                continue

            mentions.append(
                {
                    "entity": entity,
                    "alias": alias,
                    "start": start,
                    "end": end,
                    "matched_text": (
                        match.group(0)
                    ),
                }
            )

            occupied_ranges.append(
                (start, end)
            )

    mentions.sort(
        key=lambda item: (
            item["start"],
            item["end"],
        )
    )

    return mentions


# ---------------------------------------------------------------------
# 5. Metric extraction
# ---------------------------------------------------------------------

def detect_metrics(text):
    normalized_text = (
        normalize_query_text(
            text
        )
    )

    detected_metrics = []
    occupied_spans = []

    for rule in METRIC_RULES:
        for pattern in rule[
            "patterns"
        ]:
            match = re.search(
                pattern,
                normalized_text,
            )

            if not match:
                continue

            start, end = match.span()

            overlaps_existing = any(
                start < existing_end
                and end > existing_start
                for (
                    existing_start,
                    existing_end,
                )
                in occupied_spans
            )

            if overlaps_existing:
                continue

            detected_metrics.append(
                {
                    "canonical": (
                        rule["canonical"]
                    ),
                    "label": rule[
                        "label"
                    ],
                    "quantitative": (
                        rule["quantitative"]
                    ),
                    "matched_text": (
                        match.group(0)
                    ),
                    "start": start,
                    "end": end,
                }
            )

            occupied_spans.append(
                (start, end)
            )

            break

    detected_metrics.sort(
        key=lambda item: (
            item["start"],
            item["end"],
        )
    )

    return detected_metrics


# ---------------------------------------------------------------------
# 6. Period extraction
# ---------------------------------------------------------------------

def detect_periods(text):
    normalized_text = (
        normalize_query_text(
            text
        )
    )

    periods = []
    occupied_spans = []

    period_patterns = [
        {
            "kind": "quarter",
            "pattern": (
                r"\bq([1-4])\s+"
                r"((?:19|20)\d{2})\b"
            ),
        },
        {
            "kind": "fiscal_year",
            "pattern": (
                r"\bfiscal\s+year\s+"
                r"((?:19|20)\d{2})\b"
            ),
        },
        {
            "kind": "calendar_year",
            "pattern": (
                r"\bcalendar\s+year\s+"
                r"((?:19|20)\d{2})\b"
            ),
        },
        {
            "kind": "year_unspecified",
            "pattern": (
                r"\b((?:19|20)\d{2})\b"
            ),
        },
    ]

    for period_rule in period_patterns:
        for match in re.finditer(
            period_rule["pattern"],
            normalized_text,
        ):
            start, end = match.span()

            overlaps_existing = any(
                start < existing_end
                and end > existing_start
                for (
                    existing_start,
                    existing_end,
                )
                in occupied_spans
            )

            if overlaps_existing:
                continue

            kind = period_rule[
                "kind"
            ]

            if kind == "quarter":
                quarter = int(
                    match.group(1)
                )

                year = int(
                    match.group(2)
                )

                label = (
                    f"Q{quarter} {year}"
                )

            else:
                quarter = None

                year = int(
                    match.group(1)
                )

                if kind == "fiscal_year":
                    label = (
                        f"fiscal year {year}"
                    )

                elif kind == "calendar_year":
                    label = (
                        f"calendar year {year}"
                    )

                else:
                    label = str(year)

            periods.append(
                {
                    "kind": kind,
                    "year": year,
                    "quarter": quarter,
                    "label": label,
                    "matched_text": (
                        match.group(0)
                    ),
                    "start": start,
                    "end": end,
                }
            )

            occupied_spans.append(
                (start, end)
            )

    periods.sort(
        key=lambda item: (
            item["start"],
            item["end"],
        )
    )

    return periods


# ---------------------------------------------------------------------
# 7. Comparison and document-scope detection
# ---------------------------------------------------------------------

def has_comparison_intent(
    normalized_question,
):
    return any(
        re.search(
            pattern,
            normalized_question,
        )
        for pattern
        in COMPARISON_PATTERNS
    )


def has_document_scope_intent(
    normalized_question,
):
    return any(
        re.search(
            pattern,
            normalized_question,
        )
        for pattern
        in DOCUMENT_SCOPE_PATTERNS
    )


# ---------------------------------------------------------------------
# 8. Entity-specific segment extraction
# ---------------------------------------------------------------------

def build_entity_segments(
    normalized_question,
    entity_mentions,
):
    """
    Split a multi-entity question into entity-specific spans.

    Example:
    Compare Apple's fiscal 2025 net sales
    with Tesla's Q4 2025 revenue.

    Apple segment:
    compare apple's fiscal year 2025 net sales with

    Tesla segment:
    tesla's q4 2025 revenue
    """
    if not entity_mentions:
        return []

    unique_mentions = []

    seen_entities = set()

    for mention in entity_mentions:
        if mention["entity"] in seen_entities:
            continue

        seen_entities.add(
            mention["entity"]
        )

        unique_mentions.append(
            mention
        )

    segments = []

    for mention_index, mention in enumerate(
        unique_mentions
    ):
        if mention_index == 0:
            segment_start = 0
        else:
            segment_start = mention[
                "start"
            ]

        if (
            mention_index + 1
            < len(unique_mentions)
        ):
            segment_end = unique_mentions[
                mention_index + 1
            ]["start"]
        else:
            segment_end = len(
                normalized_question
            )

        segment_text = (
            normalized_question[
                segment_start:segment_end
            ]
            .strip(
                " ,.;:-"
            )
        )

        segments.append(
            {
                "entity": mention[
                    "entity"
                ],
                "segment": segment_text,
            }
        )

    return segments


# ---------------------------------------------------------------------
# 9. Clarification generator
# ---------------------------------------------------------------------

def build_clarification_message(
    entities,
    metrics,
    periods,
    reason,
):
    entity_list = sorted(
        ORCHESTRATOR_ENTITY_REGISTRY
        .keys()
    )

    entity_text = " or ".join(
        entity_list
    )

    metric_label = (
        metrics[0]["label"]
        if metrics
        else "the requested information"
    )

    if reason == "missing_entity":
        return (
            f"Which company do you mean: "
            f"{entity_text}? Please also specify "
            f"the reporting period for "
            f"{metric_label}."
        )

    if reason == "multiple_entities_without_comparison":
        return (
            "Your question refers to multiple companies. "
            "Should I compare them, or answer for only "
            "one company?"
        )

    if reason == "unspecified_period_scope":
        return (
            "Please specify whether you mean a fiscal "
            "year, calendar year, or a particular quarter."
        )

    return (
        "Please specify the company, metric, "
        "and reporting period."
    )


# ---------------------------------------------------------------------
# 10. Main Query Analyzer V1
# ---------------------------------------------------------------------

def analyze_query_v1(question):
    original_question = str(
        question or ""
    ).strip()

    if not original_question:
        raise ValueError(
            "Question cannot be empty."
        )

    normalized_question = (
        normalize_query_text(
            original_question
        )
    )

    entity_mentions = (
        detect_entity_mentions(
            normalized_question
        )
    )

    entities = []

    for mention in entity_mentions:
        if mention["entity"] not in entities:
            entities.append(
                mention["entity"]
            )

    metrics = detect_metrics(
        normalized_question
    )

    periods = detect_periods(
        normalized_question
    )

    comparison_intent = (
        has_comparison_intent(
            normalized_question
        )
    )

    document_scope_intent = (
        has_document_scope_intent(
            normalized_question
        )
    )

    corpus_entities = sorted(
        ORCHESTRATOR_ENTITY_REGISTRY
        .keys()
    )

    query_type = None
    needs_clarification = False
    clarification_reason = None
    clarification_message = None
    subqueries = []

    # -------------------------------------------------------------
    # A. Comparison query
    # -------------------------------------------------------------

    if (
        comparison_intent
        and len(entities) >= 2
    ):
        query_type = "comparison"

        entity_segments = (
            build_entity_segments(
                normalized_question,
                entity_mentions,
            )
        )

        for segment_entry in (
            entity_segments
        ):
            segment_metrics = (
                detect_metrics(
                    segment_entry[
                        "segment"
                    ]
                )
            )

            segment_periods = (
                detect_periods(
                    segment_entry[
                        "segment"
                    ]
                )
            )

            subqueries.append(
                {
                    "entity": (
                        segment_entry[
                            "entity"
                        ]
                    ),
                    "metric": (
                        deepcopy(
                            segment_metrics[0]
                        )
                        if segment_metrics
                        else None
                    ),
                    "period": (
                        deepcopy(
                            segment_periods[0]
                        )
                        if segment_periods
                        else None
                    ),
                    "segment": (
                        segment_entry[
                            "segment"
                        ]
                    ),
                    "retrieval_query": (
                        segment_entry[
                            "segment"
                        ]
                    ),
                }
            )

    # -------------------------------------------------------------
    # B. Multiple named entities without comparison intent
    # -------------------------------------------------------------

    elif len(entities) >= 2:
        query_type = "ambiguous"
        needs_clarification = True

        clarification_reason = (
            "multiple_entities_without_comparison"
        )

        clarification_message = (
            build_clarification_message(
                entities=entities,
                metrics=metrics,
                periods=periods,
                reason=clarification_reason,
            )
        )

    # -------------------------------------------------------------
    # C. One explicit entity
    # -------------------------------------------------------------

    elif len(entities) == 1:
        query_type = "single_entity"

        subqueries.append(
            {
                "entity": entities[0],
                "metric": (
                    deepcopy(metrics[0])
                    if metrics
                    else None
                ),
                "period": (
                    deepcopy(periods[0])
                    if periods
                    else None
                ),
                "segment": (
                    normalized_question
                ),
                "retrieval_query": (
                    normalized_question
                ),
            }
        )

    # -------------------------------------------------------------
    # D. No entity in a mixed tenant, but financial/document metric
    # -------------------------------------------------------------

    elif (
        len(corpus_entities) > 1
        and (
            metrics
            or periods
        )
    ):
        query_type = "ambiguous"
        needs_clarification = True
        clarification_reason = (
            "missing_entity"
        )

        clarification_message = (
            build_clarification_message(
                entities=entities,
                metrics=metrics,
                periods=periods,
                reason=clarification_reason,
            )
        )

    # -------------------------------------------------------------
    # E. Generic document-wide question
    # -------------------------------------------------------------

    elif document_scope_intent:
        query_type = "corpus_general"

    # -------------------------------------------------------------
    # F. Likely unrelated / unsupported question
    # -------------------------------------------------------------

    else:
        query_type = (
            "no_answer_candidate"
        )

    # -------------------------------------------------------------
    # Detect comparison period-scope mismatch
    # -------------------------------------------------------------

    period_scope_mismatch = False
    period_scope_warning = None

    if query_type == "comparison":
        comparison_periods = [
            subquery["period"]
            for subquery in subqueries
            if subquery[
                "period"
            ] is not None
        ]

        period_kinds = {
            period["kind"]
            for period
            in comparison_periods
        }

        if (
            "quarter" in period_kinds
            and (
                "fiscal_year"
                in period_kinds
                or "calendar_year"
                in period_kinds
            )
        ):
            period_scope_mismatch = True

            period_scope_warning = (
                "The comparison mixes an annual figure "
                "with a quarterly figure, so the values "
                "are not directly period-equivalent."
            )

    analysis = {
        "original_question": (
            original_question
        ),
        "normalized_question": (
            normalized_question
        ),
        "query_type": query_type,
        "entities": entities,
        "entity_mentions": (
            entity_mentions
        ),
        "metrics": metrics,
        "periods": periods,
        "comparison_intent": (
            comparison_intent
        ),
        "document_scope_intent": (
            document_scope_intent
        ),
        "needs_clarification": (
            needs_clarification
        ),
        "clarification_reason": (
            clarification_reason
        ),
        "clarification_message": (
            clarification_message
        ),
        "subqueries": subqueries,
        "period_scope_mismatch": (
            period_scope_mismatch
        ),
        "period_scope_warning": (
            period_scope_warning
        ),
        "available_corpus_entities": (
            corpus_entities
        ),
    }

    return analysis


# ---------------------------------------------------------------------
# 11. Human-readable diagnostic output
# ---------------------------------------------------------------------

def print_query_analysis(
    analysis,
):
    print("\n" + "=" * 92)

    print(
        f"❓ Question: "
        f"{analysis['original_question']}"
    )

    print(
        f"🧭 Query type: "
        f"{analysis['query_type']}"
    )

    print(
        f"🏷️ Entities: "
        f"{analysis['entities']}"
    )

    metric_labels = [
        metric["label"]
        for metric
        in analysis["metrics"]
    ]

    print(
        f"📊 Metrics: "
        f"{metric_labels}"
    )

    period_labels = [
        period["label"]
        for period
        in analysis["periods"]
    ]

    print(
        f"📅 Periods: "
        f"{period_labels}"
    )

    print(
        f"⚖️ Comparison intent: "
        f"{analysis['comparison_intent']}"
    )

    if analysis[
        "subqueries"
    ]:
        print(
            "🔎 Planned subqueries:"
        )

        for index, subquery in enumerate(
            analysis["subqueries"],
            start=1,
        ):
            metric_label = (
                subquery["metric"][
                    "label"
                ]
                if subquery["metric"]
                else "not detected"
            )

            period_label = (
                subquery["period"][
                    "label"
                ]
                if subquery["period"]
                else "not detected"
            )

            print(
                f"   {index}. "
                f"Entity={subquery['entity']} | "
                f"Metric={metric_label} | "
                f"Period={period_label}"
            )

            print(
                f"      Retrieval query: "
                f"{subquery['retrieval_query']}"
            )

    if analysis[
        "period_scope_mismatch"
    ]:
        print(
            "⚠️ Period warning: "
            + analysis[
                "period_scope_warning"
            ]
        )

    if analysis[
        "needs_clarification"
    ]:
        print(
            "💬 Clarification: "
            + analysis[
                "clarification_message"
            ]
        )


