PERIOD_WARNING_MARKERS = [
    "fiscal year",
    "quarter",
    "different reporting periods",
    "not directly comparable",
    "not directly period-equivalent",
    "not period-equivalent",
    "annual",
    "quarterly",
]


# ---------------------------------------------------------------------
# 3. Define validation helpers
# ---------------------------------------------------------------------

def normalize_text(
    value,
):
    return str(
        value or ""
    ).strip().lower()


def collect_source_search_text(
    source_cards,
):
    source_parts = []

    for source_card in source_cards:
        if not isinstance(
            source_card,
            dict,
        ):
            continue

        for field_name in [
            "filename",
            "section",
            "entity",
            "metric",
            "period",
            "value",
        ]:
            field_value = source_card.get(
                field_name
            )

            if field_value is not None:
                source_parts.append(
                    str(field_value)
                )

    return normalize_text(
        " ".join(source_parts)
    )


def validate_legacy_web_results(
    web_results,
):
    errors = []

    if not isinstance(
        web_results,
        list,
    ):
        return [
            "result['results'] must be a list."
        ]

    for index, web_result in enumerate(
        web_results,
        start=1,
    ):
        if not hasattr(
            web_result,
            "payload",
        ):
            errors.append(
                f"Web result {index} has no payload."
            )
            continue

        if not isinstance(
            web_result.payload,
            dict,
        ):
            errors.append(
                f"Web result {index} payload "
                "is not a dictionary."
            )

        if not hasattr(
            web_result,
            "score",
        ):
            errors.append(
                f"Web result {index} has no score."
            )

        else:
            try:
                float(
                    web_result.score
                )

            except (
                TypeError,
                ValueError,
            ):
                errors.append(
                    f"Web result {index} score "
                    "is not numeric."
                )

    return errors


def validate_serialized_sources(
    web_results,
):
    try:
        serialized_sources = (
            WEB_SOURCE_SERIALIZER(
                web_results
            )
        )

    except Exception as error:
        return (
            None,
            [
                "serialize_sources() failed: "
                f"{type(error).__name__}: {error}"
            ],
        )

    if not isinstance(
        serialized_sources,
        list,
    ):
        return (
            serialized_sources,
            [
                "serialize_sources() did not "
                "return a list."
            ],
        )

    return (
        serialized_sources,
        [],
    )


def validate_web_adapter_case(
    test_case,
    result,
):
    errors = []

    if not isinstance(
        result,
        dict,
    ):
        return [
            "The adapter result is not a dictionary."
        ]


    required_fields = {
        "tenant_id",
        "question",
        "status",
        "answer",
        "results",
        "sources",
    }

    missing_fields = (
        required_fields
        - set(
            result
        )
    )

    if missing_fields:
        errors.append(
            "Missing adapter fields: "
            + ", ".join(
                sorted(
                    missing_fields
                )
            )
        )


    returned_tenant_id = normalize_text(
        result.get(
            "tenant_id"
        )
    )

    expected_tenant_id = normalize_text(
        ORCHESTRATOR_TENANT_ID
    )

    if (
        returned_tenant_id
        != expected_tenant_id
    ):
        errors.append(
            "Trusted tenant preservation failed. "
            f"Expected {ORCHESTRATOR_TENANT_ID!r}, "
            f"received {result.get('tenant_id')!r}."
        )


    returned_question = normalize_text(
        result.get(
            "question"
        )
    )

    expected_question = normalize_text(
        test_case[
            "question"
        ]
    )

    if (
        returned_question
        != expected_question
    ):
        errors.append(
            "The adapter did not preserve "
            "the original question."
        )


    status = str(
        result.get(
            "status"
        )
        or ""
    ).strip()

    if (
        status
        not in test_case[
            "accepted_statuses"
        ]
    ):
        errors.append(
            f"Unexpected status {status!r}. "
            "Accepted statuses: "
            f"{sorted(test_case['accepted_statuses'])}."
        )


    answer = str(
        result.get(
            "answer"
        )
        or ""
    ).strip()

    if not answer:
        errors.append(
            "The adapter returned an empty answer."
        )


    normalized_answer = normalize_text(
        answer
    )

    for required_fragment in (
        test_case[
            "required_answer_fragments"
        ]
    ):
        if (
            normalize_text(
                required_fragment
            )
            not in normalized_answer
        ):
            errors.append(
                "Required answer fragment "
                f"{required_fragment!r} was not found."
            )


    source_cards = (
        result.get(
            "sources"
        )
        or []
    )

    if not isinstance(
        source_cards,
        list,
    ):
        errors.append(
            "The sources field is not a list."
        )
        source_cards = []


    source_count = len(
        source_cards
    )

    minimum_source_count = (
        test_case[
            "minimum_source_count"
        ]
    )

    maximum_source_count = (
        test_case[
            "maximum_source_count"
        ]
    )

    if (
        source_count
        < minimum_source_count
    ):
        errors.append(
            f"Expected at least "
            f"{minimum_source_count} sources, "
            f"received {source_count}."
        )

    if (
        maximum_source_count is not None
        and source_count
        > maximum_source_count
    ):
        errors.append(
            f"Expected at most "
            f"{maximum_source_count} sources, "
            f"received {source_count}."
        )


    source_search_text = (
        collect_source_search_text(
            source_cards
        )
    )

    for required_marker in (
        test_case[
            "required_source_markers"
        ]
    ):
        if (
            normalize_text(
                required_marker
            )
            not in source_search_text
        ):
            errors.append(
                "Required source marker "
                f"{required_marker!r} was not found."
            )


    if test_case[
        "require_period_warning"
    ]:
        period_warning_found = any(
            normalize_text(
                marker
            )
            in normalized_answer
            for marker in (
                PERIOD_WARNING_MARKERS
            )
        )

        if not period_warning_found:
            errors.append(
                "The comparison answer did not "
                "include a reporting-period warning."
            )


    expected_llm_called = (
        test_case[
            "expect_llm_called"
        ]
    )

    returned_llm_called = (
        result.get(
            "llm_called"
        )
    )

    if (
        expected_llm_called is False
        and returned_llm_called is not False
    ):
        errors.append(
            "The LLM should not have been called "
            f"for this scenario. Received: "
            f"{returned_llm_called!r}."
        )

    if (
        expected_llm_called is True
        and returned_llm_called not in {
            True,
            False,
        }
    ):
        errors.append(
            "The answerable scenario did not return "
            "a valid llm_called boolean."
        )


    web_results = (
        result.get(
            "results"
        )
    )

    errors.extend(
        validate_legacy_web_results(
            web_results
        )
    )


    serialized_sources, serializer_errors = (
        validate_serialized_sources(
            web_results
        )
    )

    errors.extend(
        serializer_errors
    )


    if (
        serialized_sources is not None
        and len(
            serialized_sources
        )
        != len(
            web_results
        )
    ):
        errors.append(
            "serialize_sources() returned a different "
            "source count than the adapter results."
        )


    return errors


# ---------------------------------------------------------------------
# 4. Execute controlled adapter regression tests
# ---------------------------------------------------------------------

WEB_ADAPTER_REGRESSION_RESULTS = {}

passed_count = 0
failed_count = 0


print("=" * 96)
print("🧪 CELL 22C — CONTROLLED WEB ADAPTER REGRESSION")


for test_case in (
    WEB_ADAPTER_REGRESSION_CASES
):
    print("\n" + "-" * 96)

    print(
        f"Test: "
        f"{test_case['name']}"
    )

    print(
        f"Question: "
        f"{test_case['question']}"
    )

    started_at = time.perf_counter()

    try:
        result = (
            answer_question_v2_web_adapter(
                tenant_id=(
                    ORCHESTRATOR_TENANT_ID
                ),
                question=(
                    test_case[
                        "question"
                    ]
                ),
            )
        )

        elapsed_seconds = (
            time.perf_counter()
            - started_at
        )

        validation_errors = (
            validate_web_adapter_case(
                test_case,
                result,
            )
        )

    except Exception as error:
        elapsed_seconds = (
            time.perf_counter()
            - started_at
        )

        result = None

        validation_errors = [
            f"{type(error).__name__}: {error}"
        ]


    passed = not validation_errors

    if passed:
        passed_count += 1
        status_label = "PASS"

    else:
        failed_count += 1
        status_label = "FAIL"


    WEB_ADAPTER_REGRESSION_RESULTS[
        test_case["name"]
    ] = {
        "passed": passed,
        "elapsed_seconds": (
            elapsed_seconds
        ),
        "errors": (
            validation_errors
        ),
        "result": result,
    }


    print(
        f"Result: {status_label}"
    )

    print(
        f"Elapsed: "
        f"{elapsed_seconds:.2f} seconds"
    )


    if result is not None:
        print(
            f"Status: "
            f"{result.get('status')}"
        )

        print(
            f"Tenant: "
            f"{result.get('tenant_id')}"
        )

        print(
            f"LLM called: "
            f"{result.get('llm_called')}"
        )

        print(
            f"Verified sources: "
            f"{len(result.get('sources') or [])}"
        )

        print(
            f"Web results: "
            f"{len(result.get('results') or [])}"
        )

        print(
            "Answer:"
        )

        print(
            result.get(
                "answer"
            )
        )


    if validation_errors:
        print(
            "Validation errors:"
        )

        for validation_error in (
            validation_errors
        ):
            print(
                f"   - {validation_error}"
            )


