# PHASE 3.8 - Cell 23B:
# Create organization-scoped MCP connector credentials.
#
# PURPOSE:
# - Introduce a real connector identity layer
# - Store only cryptographic token hashes
# - Bind every credential to one Organization
# - Support lookup, revoke, rotate, and last-used tracking
#
# IMPORTANT:
# - The plaintext token is NEVER stored in SQLite
# - tenant_id is NOT part of the MCP tool arguments
# - The existing MCP server/tool is NOT replaced yet
# - Cell 23C will connect credential resolution to MCP
#
# NOTE:
# This is still a notebook/runtime integration.
# During the Phase 0–3 freeze, this model will be moved
# permanently into vaultify_web_backend.py.

import hashlib
import hmac
import secrets

from datetime import datetime, timezone
from sqlalchemy import UniqueConstraint


# ---------------------------------------------------------------------
# 1. Validate Phase 3.8 inventory and Flask database
# ---------------------------------------------------------------------

required_names = [
    "MCP_PHASE_38_INVENTORY_READY",
    "vaultify_web_app",
    "vaultify_web_backend",
    "db",
    "Organization",
    "DEMO_TENANT_ID",
]

missing_names = [
    name
    for name in required_names
    if name not in globals()
]


if missing_names:
    raise RuntimeError(
        "Missing required Phase 3.8 components: "
        + ", ".join(missing_names)
        + ". Run Cells 13 and 23A first."
    )


if not MCP_PHASE_38_INVENTORY_READY:
    raise RuntimeError(
        "Cell 23A MCP inventory did not complete."
    )


print("=" * 96)
print("🔐 PHASE 3.8 — CELL 23B CONNECTOR CREDENTIAL FOUNDATION")


# ---------------------------------------------------------------------
# 2. UTC timestamp helper
# ---------------------------------------------------------------------

def connector_utc_now():
    return datetime.now(
        timezone.utc
    )


# ---------------------------------------------------------------------
# 3. Secure token format and hashing
# ---------------------------------------------------------------------

CONNECTOR_TOKEN_PREFIX = (
    "vlt_mcp_"
)

CONNECTOR_RANDOM_BYTES = 32


def generate_connector_token():
    """
    Generate a high-entropy MCP connector token.

    Example logical format:

        vlt_mcp_<random-secret>

    The complete token is returned ONLY to the caller.
    It must never be stored in the database.
    """

    random_secret = (
        secrets.token_urlsafe(
            CONNECTOR_RANDOM_BYTES
        )
    )

    return (
        CONNECTOR_TOKEN_PREFIX
        + random_secret
    )


def hash_connector_token(
    raw_token,
):
    """
    Produce the deterministic lookup hash stored in SQLite.

    Connector tokens are generated with high entropy,
    unlike human passwords, so SHA-256 is appropriate
    for indexed credential lookup.
    """

    cleaned_token = str(
        raw_token or ""
    ).strip()

    if not cleaned_token:
        raise ValueError(
            "Connector token cannot be empty."
        )

    return hashlib.sha256(
        cleaned_token.encode(
            "utf-8"
        )
    ).hexdigest()


def connector_token_display_prefix(
    raw_token,
):
    """
    Return a non-secret prefix useful for identifying
    a token in the UI without storing the full token.
    """

    cleaned_token = str(
        raw_token or ""
    ).strip()

    if not cleaned_token.startswith(
        CONNECTOR_TOKEN_PREFIX
    ):
        raise ValueError(
            "Invalid Vaultify MCP token format."
        )

    return cleaned_token[:18]


# ---------------------------------------------------------------------
# 4. Define ConnectorCredential only once
# ---------------------------------------------------------------------

existing_connector_model = getattr(
    vaultify_web_backend,
    "ConnectorCredential",
    None,
)


if existing_connector_model is not None:
    ConnectorCredential = (
        existing_connector_model
    )

    print(
        "ℹ️ Existing ConnectorCredential "
        "model will be reused."
    )

else:

    class ConnectorCredential(
        db.Model
    ):
        __tablename__ = (
            "connector_credentials"
        )

        id = db.Column(
            db.Integer,
            primary_key=True,
        )

        organization_id = db.Column(
            db.Integer,
            db.ForeignKey(
                "organizations.id",
                ondelete="CASCADE",
            ),
            nullable=False,
            index=True,
        )

        name = db.Column(
            db.String(120),
            nullable=False,
            default=(
                "Claude MCP Connector"
            ),
        )

        token_hash = db.Column(
            db.String(64),
            nullable=False,
            unique=True,
            index=True,
        )

        token_prefix = db.Column(
            db.String(32),
            nullable=False,
            index=True,
        )

        is_active = db.Column(
            db.Boolean,
            nullable=False,
            default=True,
            index=True,
        )

        last_used_at = db.Column(
            db.DateTime(
                timezone=True
            ),
            nullable=True,
        )

        created_at = db.Column(
            db.DateTime(
                timezone=True
            ),
            nullable=False,
            default=connector_utc_now,
        )

        revoked_at = db.Column(
            db.DateTime(
                timezone=True
            ),
            nullable=True,
        )

        organization = db.relationship(
            "Organization",
        )


    # Expose the runtime model through the backend module
    # so later MCP integration cells have one canonical reference.
    vaultify_web_backend.ConnectorCredential = (
        ConnectorCredential
    )

    print(
        "✅ ConnectorCredential model defined."
    )


# ---------------------------------------------------------------------
# 5. Create the new database table
# ---------------------------------------------------------------------

with vaultify_web_app.app_context():

    db.create_all()

    connector_table_names = set(
        db.inspect(
            db.engine
        ).get_table_names()
    )


if (
    "connector_credentials"
    not in connector_table_names
):
    raise RuntimeError(
        "connector_credentials table "
        "was not created."
    )


print(
    "✅ connector_credentials table is ready."
)


# ---------------------------------------------------------------------
# 6. Credential creation helper
# ---------------------------------------------------------------------

def create_connector_credential(
    organization,
    name="Claude MCP Connector",
):
    """
    Create one organization-scoped connector credential.

    Returns:
        (credential_record, plaintext_token)

    Only the hash is persisted.
    """

    if organization is None:
        raise ValueError(
            "Organization is required."
        )

    raw_token = (
        generate_connector_token()
    )

    token_hash = (
        hash_connector_token(
            raw_token
        )
    )

    token_prefix = (
        connector_token_display_prefix(
            raw_token
        )
    )

    credential = (
        ConnectorCredential(
            organization_id=(
                organization.id
            ),
            name=str(
                name
                or "Claude MCP Connector"
            ).strip(),
            token_hash=token_hash,
            token_prefix=token_prefix,
            is_active=True,
        )
    )

    db.session.add(
        credential
    )

    db.session.commit()

    return (
        credential,
        raw_token,
    )


# ---------------------------------------------------------------------
# 7. Constant-time credential lookup
# ---------------------------------------------------------------------

def resolve_connector_credential(
    raw_token,
    *,
    mark_used=False,
):
    """
    Resolve a plaintext connector token to an active
    organization-bound credential.

    Returns None for invalid, unknown, or revoked tokens.
    """

    cleaned_token = str(
        raw_token or ""
    ).strip()


    if not cleaned_token.startswith(
        CONNECTOR_TOKEN_PREFIX
    ):
        return None


    token_hash = (
        hash_connector_token(
            cleaned_token
        )
    )


    credential = (
        ConnectorCredential.query
        .filter_by(
            token_hash=token_hash,
            is_active=True,
        )
        .first()
    )


    if credential is None:
        return None


    # Defensive constant-time comparison.
    if not hmac.compare_digest(
        credential.token_hash,
        token_hash,
    ):
        return None


    if mark_used:
        credential.last_used_at = (
            connector_utc_now()
        )

        db.session.commit()


    return credential


# ---------------------------------------------------------------------
# 8. Revoke helper
# ---------------------------------------------------------------------

def revoke_connector_credential(
    credential,
):
    """
    Immediately revoke a connector credential.
    """

    if credential is None:
        raise ValueError(
            "Credential is required."
        )


    if not credential.is_active:
        return credential


    credential.is_active = False

    credential.revoked_at = (
        connector_utc_now()
    )

    db.session.commit()

    return credential


# ---------------------------------------------------------------------
# 9. Rotate helper
# ---------------------------------------------------------------------

def rotate_connector_credential(
    credential,
):
    """
    Revoke an existing credential and issue a replacement.

    The replacement belongs to exactly the same organization.
    """

    if credential is None:
        raise ValueError(
            "Credential is required."
        )


    organization = (
        db.session.get(
            Organization,
            credential.organization_id,
        )
    )


    if organization is None:
        raise RuntimeError(
            "Credential organization "
            "no longer exists."
        )


    credential_name = (
        credential.name
    )


    revoke_connector_credential(
        credential
    )


    return (
        create_connector_credential(
            organization=organization,
            name=credential_name,
        )
    )


# ---------------------------------------------------------------------
# 10. Trusted tenant resolver
# ---------------------------------------------------------------------

def connector_credential_to_tenant_id(
    credential,
):
    """
    Resolve tenant identity from the credential's organization.

    No tenant_id is accepted from the external client.
    """

    if credential is None:
        raise PermissionError(
            "A valid connector credential "
            "is required."
        )


    if not credential.is_active:
        raise PermissionError(
            "The connector credential "
            "has been revoked."
        )


    organization = (
        db.session.get(
            Organization,
            credential.organization_id,
        )
    )


    if organization is None:
        raise PermissionError(
            "The connector organization "
            "does not exist."
        )


    return organization.tenant_id


