# PHASE 3.8 - Cell 23C:
# Tenant-aware runtime bridge for the approved V2 orchestrator.
#
# NOTE:
# This is a temporary notebook bridge. During the final Phase 0–3 cleanup,
# these tenant contexts will be moved into proper service objects/modules.
#
# This cell:
# - Reads tenant chunks from Qdrant
# - Builds one V2 retrieval context per tenant
# - Reuses the already-approved Cell 21B–21E logic
# - Tests cross-tenant isolation
# - Does NOT modify MCP
# - Does NOT write to Qdrant
# - Does NOT call Groq

from collections import Counter, defaultdict
from contextlib import contextmanager
import threading


# ---------------------------------------------------------------------
# 1. Validate dependencies
# ---------------------------------------------------------------------

required = [
    "MCP_CONNECTOR_CREDENTIAL_MODEL_READY",
    "answer_question_v2",
    "load_tenant_points",
    "payload_text",
    "payload_filename",
    "payload_document_hash",
    "payload_section",
    "payload_chunk_type",
    "payload_chunk_index",
    "infer_document_entities",
    "aliases_for_entities",
    "build_entity_alias_index",
    "prepare_entity_retrieval_index",
    "DEMO_TENANTS",
    "vaultify_web_backend",
]

missing = [
    name
    for name in required
    if name not in globals()
]

if missing:
    raise RuntimeError(
        "Missing Cell 23C dependencies: "
        + ", ".join(missing)
    )

if not MCP_CONNECTOR_CREDENTIAL_MODEL_READY:
    raise RuntimeError(
        "Cell 23B is not approved."
    )


print("=" * 96)
print(
    "🧭 PHASE 3.8 — CELL 23C "
    "TENANT-AWARE V2 RUNTIME BRIDGE"
)


# Preserve the approved V2 service exactly once.
if "BASE_ANSWER_QUESTION_V2" not in globals():
    BASE_ANSWER_QUESTION_V2 = (
        answer_question_v2
    )


# Rebuild this cache whenever Cell 23C itself is rerun.
TENANT_ORCHESTRATOR_CONTEXT_CACHE = {}


if (
    "TENANT_ORCHESTRATOR_CONTEXT_LOCK"
    not in globals()
):
    TENANT_ORCHESTRATOR_CONTEXT_LOCK = (
        threading.RLock()
    )


# ---------------------------------------------------------------------
# 2. Temporary global binding helper
# ---------------------------------------------------------------------

_MISSING = object()


@contextmanager
def temporary_orchestrator_globals(
    values,
):
    """
    Temporarily bind the global objects expected by
    the already-approved Cells 21B–21E.
    """

    previous = {
        name: globals().get(
            name,
            _MISSING,
        )
        for name in values
    }

    try:
        globals().update(
            values
        )

        yield

    finally:
        for name, value in (
            previous.items()
        ):
            if value is _MISSING:
                globals().pop(
                    name,
                    None,
                )

            else:
                globals()[
                    name
                ] = value


# ---------------------------------------------------------------------
# 3. Load one tenant into the normalized Cell 21A chunk shape
# ---------------------------------------------------------------------

def load_tenant_chunks_v2(
    tenant_id,
):
    points = load_tenant_points(
        tenant_id
    )

    if not points:
        raise RuntimeError(
            "No Qdrant points found for "
            f"tenant '{tenant_id}'."
        )

    chunks = []

    for fallback_index, point in enumerate(
        points
    ):
        payload = point.payload or {}

        text = payload_text(
            payload
        )

        if not text:
            continue

        chunks.append(
            {
                "point_id": str(
                    point.id
                ),
                "tenant_id": (
                    tenant_id
                ),
                "filename": (
                    payload_filename(
                        payload
                    )
                ),
                "document_hash": (
                    payload_document_hash(
                        payload
                    )
                ),
                "chunk_index": (
                    payload_chunk_index(
                        payload,
                        fallback_index,
                    )
                ),
                "chunk_type": (
                    payload_chunk_type(
                        payload
                    )
                ),
                "section": (
                    payload_section(
                        payload
                    )
                ),
                "text": text,
                "payload": payload,
            }
        )

    if not chunks:
        raise RuntimeError(
            "No usable chunks found for "
            f"tenant '{tenant_id}'."
        )

    return chunks


# ---------------------------------------------------------------------
# 4. Build the minimum catalog/registry contract
#    required by Cells 21B–21E
# ---------------------------------------------------------------------

def build_tenant_catalog_v2(
    tenant_id,
    chunks,
):
    document_groups = defaultdict(
        list
    )

    for chunk in chunks:
        document_key = (
            chunk[
                "document_hash"
            ]
            or (
                "filename::"
                + chunk[
                    "filename"
                ].lower()
            )
        )

        document_groups[
            document_key
        ].append(
            chunk
        )

    catalog = {}

    registry = defaultdict(
        lambda: {
            "aliases": set(),
            "document_keys": set(),
            "filenames": set(),
        }
    )

    for (
        document_key,
        document_chunks,
    ) in document_groups.items():

        document_chunks.sort(
            key=lambda item: (
                item[
                    "chunk_index"
                ],
                item[
                    "point_id"
                ],
            )
        )

        filename = Counter(
            item[
                "filename"
            ]
            for item
            in document_chunks
        ).most_common(
            1
        )[0][0]

        document_hash = next(
            (
                item[
                    "document_hash"
                ]
                for item
                in document_chunks
                if item[
                    "document_hash"
                ]
            ),
            None,
        )

        entities = (
            infer_document_entities(
                filename=filename,
                chunks=(
                    document_chunks
                ),
            )
        )

        aliases = (
            aliases_for_entities(
                entities
            )
        )

        catalog[
            document_key
        ] = {
            "document_key": (
                document_key
            ),
            "filename": (
                filename
            ),
            "document_hash": (
                document_hash
            ),
            "tenant_id": (
                tenant_id
            ),
            "entities": (
                entities
            ),
            "aliases": (
                aliases
            ),
            "chunks": (
                document_chunks
            ),
        }

        for entity in entities:
            registry[
                entity
            ][
                "aliases"
            ].update(
                aliases
            )

            registry[
                entity
            ][
                "document_keys"
            ].add(
                document_key
            )

            registry[
                entity
            ][
                "filenames"
            ].add(
                filename
            )

    stable_registry = {
        entity: {
            "aliases": sorted(
                metadata[
                    "aliases"
                ]
            ),
            "document_keys": sorted(
                metadata[
                    "document_keys"
                ]
            ),
            "filenames": sorted(
                metadata[
                    "filenames"
                ]
            ),
        }
        for entity, metadata
        in registry.items()
    }

    if not stable_registry:
        raise RuntimeError(
            "Entity registry is empty "
            f"for tenant '{tenant_id}'."
        )

    return (
        catalog,
        stable_registry,
    )


# ---------------------------------------------------------------------
# 5. Build/cache one complete V2 context per tenant
# ---------------------------------------------------------------------

def build_tenant_orchestrator_context(
    tenant_id,
    force_rebuild=False,
):
    tenant_id = str(
        tenant_id or ""
    ).strip()

    if not tenant_id:
        raise ValueError(
            "tenant_id is required."
        )

    with (
        TENANT_ORCHESTRATOR_CONTEXT_LOCK
    ):

        if (
            not force_rebuild
            and tenant_id
            in TENANT_ORCHESTRATOR_CONTEXT_CACHE
        ):
            return (
                TENANT_ORCHESTRATOR_CONTEXT_CACHE[
                    tenant_id
                ]
            )

        print(
            f"\n🏢 Building V2 context: "
            f"{tenant_id}"
        )

        chunks = (
            load_tenant_chunks_v2(
                tenant_id
            )
        )

        (
            catalog,
            registry,
        ) = (
            build_tenant_catalog_v2(
                tenant_id,
                chunks,
            )
        )

        alias_index = (
            build_entity_alias_index(
                registry
            )
        )

        entity_indexes = {}

        bindings = {
            "ORCHESTRATOR_TENANT_ID": (
                tenant_id
            ),
            "ORCHESTRATOR_TENANT_CHUNKS": (
                chunks
            ),
            "ORCHESTRATOR_DOCUMENT_CATALOG": (
                catalog
            ),
            "ORCHESTRATOR_ENTITY_REGISTRY": (
                registry
            ),
            "ORCHESTRATOR_ENTITY_ALIAS_INDEX": (
                alias_index
            ),
            "ORCHESTRATOR_ENTITY_RETRIEVAL_INDEXES": (
                entity_indexes
            ),
        }

        # Reuse the approved Cell 21C
        # hybrid index builder.
        with temporary_orchestrator_globals(
            bindings
        ):
            for entity in sorted(
                registry
            ):
                entity_indexes[
                    entity
                ] = (
                    prepare_entity_retrieval_index(
                        entity
                    )
                )

        context = {
            **bindings,
            (
                "ORCHESTRATOR_"
                "ENTITY_RETRIEVAL_INDEXES"
            ): entity_indexes,
        }

        TENANT_ORCHESTRATOR_CONTEXT_CACHE[
            tenant_id
        ] = context

        print(
            f"   ✅ Chunks: "
            f"{len(chunks)}"
        )

        print(
            f"   ✅ Documents: "
            f"{len(catalog)}"
        )

        print(
            f"   ✅ Entities: "
            f"{sorted(registry)}"
        )

        return context


# ---------------------------------------------------------------------
# 6. Trusted tenant-aware wrapper
# ---------------------------------------------------------------------

def answer_question_v2_for_tenant(
    tenant_id,
    question,
    use_llm=True,
):
    """
    Run the approved V2 engine against exactly
    one trusted tenant context.

    tenant_id must come from server-side identity
    resolution, never from an MCP tool argument.
    """

    tenant_id = str(
        tenant_id or ""
    ).strip()

    if not tenant_id:
        raise ValueError(
            "tenant_id is required."
        )

    with (
        TENANT_ORCHESTRATOR_CONTEXT_LOCK
    ):

        context = (
            build_tenant_orchestrator_context(
                tenant_id
            )
        )

        with temporary_orchestrator_globals(
            context
        ):
            result = (
                BASE_ANSWER_QUESTION_V2(
                    tenant_id=(
                        tenant_id
                    ),
                    question=(
                        question
                    ),
                    use_llm=(
                        use_llm
                    ),
                )
            )

    if (
        result.get(
            "tenant_id"
        )
        != tenant_id
    ):
        raise RuntimeError(
            "The V2 service returned "
            "the wrong tenant."
        )

    return result


# Expose the bridge for Cell 23D.
vaultify_web_backend.answer_question_v2_for_tenant = (
    answer_question_v2_for_tenant
)


# ---------------------------------------------------------------------
# 7. Regression test with two real Qdrant tenants
# ---------------------------------------------------------------------

APPLE_TEST_TENANT = str(
    DEMO_TENANTS[
        "company_a"
    ][
        "tenant_id"
    ]
)

TESLA_TEST_TENANT = str(
    DEMO_TENANTS[
        "company_b"
    ][
        "tenant_id"
    ]
)


if (
    APPLE_TEST_TENANT
    == TESLA_TEST_TENANT
):
    raise RuntimeError(
        "Two different tenants "
        "are required for Cell 23C."
    )


def source_entities(
    result,
):
    return {
        str(
            source.get(
                "entity",
                "",
            )
        )
        for source
        in result.get(
            "sources",
            [],
        )
        if isinstance(
            source,
            dict,
        )
    }


def source_filenames(
    result,
):
    return {
        str(
            source.get(
                "filename",
                "",
            )
        )
        for source
        in result.get(
            "sources",
            [],
        )
        if isinstance(
            source,
            dict,
        )
    }


print(
    "\n🧪 Running tenant-aware "
    "V2 regression..."
)


# Deterministic mode is enough for tenant isolation
# and avoids unnecessary Groq calls.
apple_result = (
    answer_question_v2_for_tenant(
        APPLE_TEST_TENANT,
        (
            "What were Apple's total net sales "
            "in fiscal year 2025?"
        ),
        use_llm=False,
    )
)


tesla_result = (
    answer_question_v2_for_tenant(
        TESLA_TEST_TENANT,
        (
            "What was Tesla's total revenue "
            "in Q4 2025?"
        ),
        use_llm=False,
    )
)


negative_result = (
    answer_question_v2_for_tenant(
        TESLA_TEST_TENANT,
        (
            "What were Apple's total net sales "
            "in fiscal year 2025?"
        ),
        use_llm=False,
    )
)


apple_passed = (
    apple_result.get(
        "status"
    )
    == "answered"
    and "416,161"
    in apple_result.get(
        "answer",
        "",
    )
    and "Apple"
    in source_entities(
        apple_result
    )
)


tesla_passed = (
    tesla_result.get(
        "status"
    )
    == "answered"
    and "24,901"
    in tesla_result.get(
        "answer",
        "",
    )
    and "Tesla"
    in source_entities(
        tesla_result
    )
)


negative_files = (
    source_filenames(
        negative_result
    )
)

negative_entities = (
    source_entities(
        negative_result
    )
)


cross_tenant_passed = (
    "416,161"
    not in negative_result.get(
        "answer",
        "",
    )
    and "Apple"
    not in negative_entities
    and not any(
        "apple"
        in filename.lower()
        for filename
        in negative_files
    )
)


TENANT_AWARE_V2_ORCHESTRATOR_READY = (
    apple_passed
    and tesla_passed
    and cross_tenant_passed
)


# ---------------------------------------------------------------------
# 8. Summary
# ---------------------------------------------------------------------

print("\n" + "=" * 96)
print("📊 CELL 23C SUMMARY")


print(
    f"{'✅' if apple_passed else '❌'} "
    "Apple/mixed tenant V2"
)

print(
    f"   Status: "
    f"{apple_result.get('status')}"
)

print(
    f"   Sources: "
    f"{sorted(source_filenames(apple_result))}"
)


print(
    f"\n{'✅' if tesla_passed else '❌'} "
    "Tesla-only tenant V2"
)

print(
    f"   Status: "
    f"{tesla_result.get('status')}"
)

print(
    f"   Sources: "
    f"{sorted(source_filenames(tesla_result))}"
)


print(
    f"\n{'✅' if cross_tenant_passed else '❌'} "
    "Tesla tenant cannot access Apple evidence"
)

print(
    f"   Status: "
    f"{negative_result.get('status')}"
)

print(
    f"   Sources: "
    f"{sorted(negative_files)}"
)


print(
    "\nCached tenant contexts: "
    f"{sorted(TENANT_ORCHESTRATOR_CONTEXT_CACHE)}"
)


if not TENANT_AWARE_V2_ORCHESTRATOR_READY:
    raise RuntimeError(
        "Tenant-aware V2 regression failed. "
        "Do not connect MCP authentication yet."
    )


print(
    "\n✅ Tenant-aware V2 runtime bridge passed."
)

print(
    "✅ Different trusted tenant IDs "
    "activate different V2 indexes."
)

print(
    "✅ Apple evidence did not leak into "
    "the Tesla-only tenant."
)

print(
    "➡️ Next: Cell 23D — connector credential "
    "→ organization → trusted tenant → V2."
)

print(
    "\n⏭️ Active MCP server was not modified."
)

print(
    "⏭️ No Qdrant points were created, "
    "updated, or deleted."
)

print(
    "⏭️ No Groq request was made."
)

